insert into public.workouts (id, title, style, level, intensity, impact, minutes, summary, instructor_id, equipment, content_origin, blocks, safety, status, is_synthetic) values
('qf5-afrobeats-wake-up', 'Afrobeats Wake-Up', 'afrobeats', 'beginner', 'moderate', 'low', 5, 'A five-minute bounce-and-sway session to start the day.', null, 'none', 'original_text', '[{"kind":"warmup","title":"Easy march and shoulder rolls","seconds":30,"cue":"Walk in place and roll the shoulders to raise your heart rate gently.","lowImpactAlt":"Seated march with shoulder rolls."},{"kind":"warmup","title":"Dynamic stretches","seconds":30,"cue":"Reach overhead, side-bend, and gentle hip circles.","lowImpactAlt":"Do it seated."},{"kind":"main","title":"Bounce and sway","seconds":97,"cue":"Soft knees, bounce on the beat and let your shoulders sway side to side.","lowImpactAlt":"Same sway standing tall with small steps; no bounce."},{"kind":"main","title":"Step-tap with arm swing","seconds":98,"cue":"Step to the side, tap the other foot in, swing the arms in a relaxed arc.","lowImpactAlt":"Step without the tap; keep the arm swing low."},{"kind":"cooldown","title":"Slow walk and breathing","seconds":22,"cue":"Walk in place slowly and breathe in through the nose, out through the mouth.","lowImpactAlt":"Seated, same breathing."},{"kind":"cooldown","title":"Gentle stretches","seconds":23,"cue":"Hold calf, quad and chest stretches for about 20 seconds each, without bouncing.","lowImpactAlt":"Seated versions of each stretch."}]'::jsonb, '["Stop if you feel chest pain, dizziness or unusual shortness of breath, and speak to a health professional.","Clear a safe space, wear supportive footwear and keep water nearby.","You can switch to the low-impact version at any time; it is a full workout, not a lesser one."]'::jsonb, 'published', true),
('qf5-lowimpact-reset', 'Low-Impact Reset', 'low_impact', 'beginner', 'low', 'low', 5, 'Gentle standing movement to loosen up. Seated option throughout.', null, 'none', 'original_text', '[{"kind":"warmup","title":"Easy march and shoulder rolls","seconds":30,"cue":"Walk in place and roll the shoulders to raise your heart rate gently.","lowImpactAlt":"Seated march with shoulder rolls."},{"kind":"warmup","title":"Dynamic stretches","seconds":30,"cue":"Reach overhead, side-bend, and gentle hip circles.","lowImpactAlt":"Do it seated."},{"kind":"main","title":"March in place","seconds":97,"cue":"Lift the knees to a comfortable height and swing the arms.","lowImpactAlt":"Seated march; lift heels only."},{"kind":"main","title":"Standing knee lift","seconds":98,"cue":"Lift one knee at a time while twisting gently toward it.","lowImpactAlt":"Tap the toe to the floor instead of lifting."},{"kind":"cooldown","title":"Slow walk and breathing","seconds":22,"cue":"Walk in place slowly and breathe in through the nose, out through the mouth.","lowImpactAlt":"Seated, same breathing."},{"kind":"cooldown","title":"Gentle stretches","seconds":23,"cue":"Hold calf, quad and chest stretches for about 20 seconds each, without bouncing.","lowImpactAlt":"Seated versions of each stretch."}]'::jsonb, '["Stop if you feel chest pain, dizziness or unusual shortness of breath, and speak to a health professional.","Clear a safe space, wear supportive footwear and keep water nearby.","You can switch to the low-impact version at any time; it is a full workout, not a lesser one."]'::jsonb, 'published', true),
('qf10-amapiano-groove', 'Amapiano Groove 10', 'amapiano', 'beginner', 'moderate', 'low', 10, 'Relaxed, rhythmic grooves with soft knees. Ten minutes, easy to follow.', null, 'none', 'original_text', '[{"kind":"warmup","title":"Easy march and shoulder rolls","seconds":45,"cue":"Walk in place and roll the shoulders to raise your heart rate gently.","lowImpactAlt":"Seated march with shoulder rolls."},{"kind":"warmup","title":"Dynamic stretches","seconds":45,"cue":"Reach overhead, side-bend, and gentle hip circles.","lowImpactAlt":"Do it seated."},{"kind":"main","title":"Slow groove sway","seconds":110,"cue":"Deep, relaxed sway with soft knees; let the hips lead.","lowImpactAlt":"Smaller sway, feet stay planted."},{"kind":"main","title":"Knee-pulse step","seconds":110,"cue":"Pulse both knees in time while stepping side to side.","lowImpactAlt":"Shift weight side to side without pulsing."},{"kind":"main","title":"Cross-step glide","seconds":110,"cue":"Cross one foot in front, glide it back, alternate sides.","lowImpactAlt":"Tap instead of crossing; keep steps small."},{"kind":"main","title":"Shoulder roll flow","seconds":110,"cue":"Roll the shoulders back in time while keeping a steady step.","lowImpactAlt":"Roll the shoulders standing still."},{"kind":"cooldown","title":"Slow walk and breathing","seconds":35,"cue":"Walk in place slowly and breathe in through the nose, out through the mouth.","lowImpactAlt":"Seated, same breathing."},{"kind":"cooldown","title":"Gentle stretches","seconds":35,"cue":"Hold calf, quad and chest stretches for about 20 seconds each, without bouncing.","lowImpactAlt":"Seated versions of each stretch."}]'::jsonb, '["Stop if you feel chest pain, dizziness or unusual shortness of breath, and speak to a health professional.","Clear a safe space, wear supportive footwear and keep water nearby.","You can switch to the low-impact version at any time; it is a full workout, not a lesser one."]'::jsonb, 'published', true),
('qf10-hiphop-bounce', 'Hip-Hop Bounce 10', 'hip_hop', 'intermediate', 'high', 'moderate', 10, 'Low stance, strong arms and quick steps in a short, punchy session.', null, 'none', 'original_text', '[{"kind":"warmup","title":"Easy march and shoulder rolls","seconds":45,"cue":"Walk in place and roll the shoulders to raise your heart rate gently.","lowImpactAlt":"Seated march with shoulder rolls."},{"kind":"warmup","title":"Dynamic stretches","seconds":45,"cue":"Reach overhead, side-bend, and gentle hip circles.","lowImpactAlt":"Do it seated."},{"kind":"main","title":"Bounce and rock","seconds":110,"cue":"Bounce in a low stance and rock your weight forward and back.","lowImpactAlt":"Rock forward and back without bouncing."},{"kind":"main","title":"Step-clap","seconds":110,"cue":"Step out wide, clap, step in, clap.","lowImpactAlt":"Step out with one foot at a time, skip the wide stance."},{"kind":"main","title":"Arm-line groove","seconds":110,"cue":"Make sharp arm lines (up, across, down) over a steady bounce.","lowImpactAlt":"Make the arm lines slowly, standing still."},{"kind":"main","title":"Quarter-turn step","seconds":110,"cue":"Step and turn a quarter each time with a pause on the beat.","lowImpactAlt":"Face forward and step side to side."},{"kind":"cooldown","title":"Slow walk and breathing","seconds":35,"cue":"Walk in place slowly and breathe in through the nose, out through the mouth.","lowImpactAlt":"Seated, same breathing."},{"kind":"cooldown","title":"Gentle stretches","seconds":35,"cue":"Hold calf, quad and chest stretches for about 20 seconds each, without bouncing.","lowImpactAlt":"Seated versions of each stretch."}]'::jsonb, '["Stop if you feel chest pain, dizziness or unusual shortness of breath, and speak to a health professional.","Clear a safe space, wear supportive footwear and keep water nearby.","You can switch to the low-impact version at any time; it is a full workout, not a lesser one."]'::jsonb, 'published', true),
('qf10-latin-rhythm', 'Latin Rhythm 10', 'latin', 'beginner', 'moderate', 'low', 10, 'Side steps, hip sway and a simple cross-body walk.', null, 'none', 'original_text', '[{"kind":"warmup","title":"Easy march and shoulder rolls","seconds":45,"cue":"Walk in place and roll the shoulders to raise your heart rate gently.","lowImpactAlt":"Seated march with shoulder rolls."},{"kind":"warmup","title":"Dynamic stretches","seconds":45,"cue":"Reach overhead, side-bend, and gentle hip circles.","lowImpactAlt":"Do it seated."},{"kind":"main","title":"Basic side step","seconds":110,"cue":"Step side, together, side, tap with relaxed hips.","lowImpactAlt":"Step side and tap without hip movement."},{"kind":"main","title":"Forward-back rhythm","seconds":110,"cue":"Step forward, rock back, replace, with a gentle hip sway.","lowImpactAlt":"Smaller steps with flat feet."},{"kind":"main","title":"Cross-body walk","seconds":110,"cue":"Walk a loose diagonal path across the room with a hip sway.","lowImpactAlt":"March in place with a slight sway."},{"kind":"main","title":"Hip circle step","seconds":110,"cue":"Circle the hips slowly on every second step.","lowImpactAlt":"Circle the hips standing still."},{"kind":"cooldown","title":"Slow walk and breathing","seconds":35,"cue":"Walk in place slowly and breathe in through the nose, out through the mouth.","lowImpactAlt":"Seated, same breathing."},{"kind":"cooldown","title":"Gentle stretches","seconds":35,"cue":"Hold calf, quad and chest stretches for about 20 seconds each, without bouncing.","lowImpactAlt":"Seated versions of each stretch."}]'::jsonb, '["Stop if you feel chest pain, dizziness or unusual shortness of breath, and speak to a health professional.","Clear a safe space, wear supportive footwear and keep water nearby.","You can switch to the low-impact version at any time; it is a full workout, not a lesser one."]'::jsonb, 'published', true),
('qf10-bollywood-energy', 'Bollywood Energy 10', 'bollywood', 'intermediate', 'moderate', 'moderate', 10, 'Big arm sweeps, shimmies and a slow turn.', null, 'none', 'original_text', '[{"kind":"warmup","title":"Easy march and shoulder rolls","seconds":45,"cue":"Walk in place and roll the shoulders to raise your heart rate gently.","lowImpactAlt":"Seated march with shoulder rolls."},{"kind":"warmup","title":"Dynamic stretches","seconds":45,"cue":"Reach overhead, side-bend, and gentle hip circles.","lowImpactAlt":"Do it seated."},{"kind":"main","title":"Arm sweep side step","seconds":110,"cue":"Sweep both arms overhead as you step wide, then bring them down.","lowImpactAlt":"Sweep the arms at chest height with small steps."},{"kind":"main","title":"Shoulder shimmy walk","seconds":110,"cue":"Walk forward four steps with a light shoulder shimmy.","lowImpactAlt":"Shimmy the shoulders while marching in place."},{"kind":"main","title":"Spin and pose","seconds":110,"cue":"Turn once slowly and hold a tall pose for a beat.","lowImpactAlt":"Replace the turn with a step-and-pose."},{"kind":"main","title":"Hand-flow step","seconds":110,"cue":"Float the hands in soft circles as you step side to side.","lowImpactAlt":"Same hand flow seated or with feet planted."},{"kind":"cooldown","title":"Slow walk and breathing","seconds":35,"cue":"Walk in place slowly and breathe in through the nose, out through the mouth.","lowImpactAlt":"Seated, same breathing."},{"kind":"cooldown","title":"Gentle stretches","seconds":35,"cue":"Hold calf, quad and chest stretches for about 20 seconds each, without bouncing.","lowImpactAlt":"Seated versions of each stretch."}]'::jsonb, '["Stop if you feel chest pain, dizziness or unusual shortness of breath, and speak to a health professional.","Clear a safe space, wear supportive footwear and keep water nearby.","You can switch to the low-impact version at any time; it is a full workout, not a lesser one.","Take the turn slowly and keep your eyes on a fixed point to stay balanced."]'::jsonb, 'published', true),
('qf15-afrobeats-burn', 'Afrobeats Cardio 15', 'afrobeats', 'intermediate', 'high', 'moderate', 15, 'A fifteen-minute cardio session built on bouncy, high-energy steps.', null, 'none', 'original_text', '[{"kind":"warmup","title":"Easy march and shoulder rolls","seconds":67,"cue":"Walk in place and roll the shoulders to raise your heart rate gently.","lowImpactAlt":"Seated march with shoulder rolls."},{"kind":"warmup","title":"Dynamic stretches","seconds":68,"cue":"Reach overhead, side-bend, and gentle hip circles.","lowImpactAlt":"Do it seated."},{"kind":"main","title":"Bounce and sway","seconds":163,"cue":"Soft knees, bounce on the beat and let your shoulders sway side to side.","lowImpactAlt":"Same sway standing tall with small steps; no bounce."},{"kind":"main","title":"Step-tap with arm swing","seconds":163,"cue":"Step to the side, tap the other foot in, swing the arms in a relaxed arc.","lowImpactAlt":"Step without the tap; keep the arm swing low."},{"kind":"main","title":"Heel-toe pulse","seconds":163,"cue":"Alternate heel then toe taps forward while pulsing the chest.","lowImpactAlt":"Tap the heel only, feet stay close to the floor."},{"kind":"main","title":"Grapevine groove","seconds":166,"cue":"Four steps to one side then back, adding a gentle hip roll.","lowImpactAlt":"Two steps each way with no hip roll."},{"kind":"cooldown","title":"Slow walk and breathing","seconds":55,"cue":"Walk in place slowly and breathe in through the nose, out through the mouth.","lowImpactAlt":"Seated, same breathing."},{"kind":"cooldown","title":"Gentle stretches","seconds":55,"cue":"Hold calf, quad and chest stretches for about 20 seconds each, without bouncing.","lowImpactAlt":"Seated versions of each stretch."}]'::jsonb, '["Stop if you feel chest pain, dizziness or unusual shortness of breath, and speak to a health professional.","Clear a safe space, wear supportive footwear and keep water nearby.","You can switch to the low-impact version at any time; it is a full workout, not a lesser one."]'::jsonb, 'published', true),
('qf15-lowimpact-flow', 'Low-Impact Flow 15', 'low_impact', 'beginner', 'low', 'low', 15, 'A full quarter-hour of low-impact dance fitness with seated options.', null, 'none', 'original_text', '[{"kind":"warmup","title":"Easy march and shoulder rolls","seconds":67,"cue":"Walk in place and roll the shoulders to raise your heart rate gently.","lowImpactAlt":"Seated march with shoulder rolls."},{"kind":"warmup","title":"Dynamic stretches","seconds":68,"cue":"Reach overhead, side-bend, and gentle hip circles.","lowImpactAlt":"Do it seated."},{"kind":"main","title":"March in place","seconds":163,"cue":"Lift the knees to a comfortable height and swing the arms.","lowImpactAlt":"Seated march; lift heels only."},{"kind":"main","title":"Standing knee lift","seconds":163,"cue":"Lift one knee at a time while twisting gently toward it.","lowImpactAlt":"Tap the toe to the floor instead of lifting."},{"kind":"main","title":"Step-touch","seconds":163,"cue":"Step side to side and touch the feet together.","lowImpactAlt":"Same with the smallest steps."},{"kind":"main","title":"Arm reach flow","seconds":166,"cue":"Reach up, out and across the body in a slow flow.","lowImpactAlt":"Do it seated."},{"kind":"cooldown","title":"Slow walk and breathing","seconds":55,"cue":"Walk in place slowly and breathe in through the nose, out through the mouth.","lowImpactAlt":"Seated, same breathing."},{"kind":"cooldown","title":"Gentle stretches","seconds":55,"cue":"Hold calf, quad and chest stretches for about 20 seconds each, without bouncing.","lowImpactAlt":"Seated versions of each stretch."}]'::jsonb, '["Stop if you feel chest pain, dizziness or unusual shortness of breath, and speak to a health professional.","Clear a safe space, wear supportive footwear and keep water nearby.","You can switch to the low-impact version at any time; it is a full workout, not a lesser one."]'::jsonb, 'published', true),
('qf15-latin-cardio', 'Latin Cardio 15', 'latin', 'intermediate', 'moderate', 'moderate', 15, 'Steady Latin-inspired cardio with forward-back rhythm and hip circles.', null, 'none', 'original_text', '[{"kind":"warmup","title":"Easy march and shoulder rolls","seconds":67,"cue":"Walk in place and roll the shoulders to raise your heart rate gently.","lowImpactAlt":"Seated march with shoulder rolls."},{"kind":"warmup","title":"Dynamic stretches","seconds":68,"cue":"Reach overhead, side-bend, and gentle hip circles.","lowImpactAlt":"Do it seated."},{"kind":"main","title":"Basic side step","seconds":163,"cue":"Step side, together, side, tap with relaxed hips.","lowImpactAlt":"Step side and tap without hip movement."},{"kind":"main","title":"Forward-back rhythm","seconds":163,"cue":"Step forward, rock back, replace, with a gentle hip sway.","lowImpactAlt":"Smaller steps with flat feet."},{"kind":"main","title":"Cross-body walk","seconds":163,"cue":"Walk a loose diagonal path across the room with a hip sway.","lowImpactAlt":"March in place with a slight sway."},{"kind":"main","title":"Hip circle step","seconds":166,"cue":"Circle the hips slowly on every second step.","lowImpactAlt":"Circle the hips standing still."},{"kind":"cooldown","title":"Slow walk and breathing","seconds":55,"cue":"Walk in place slowly and breathe in through the nose, out through the mouth.","lowImpactAlt":"Seated, same breathing."},{"kind":"cooldown","title":"Gentle stretches","seconds":55,"cue":"Hold calf, quad and chest stretches for about 20 seconds each, without bouncing.","lowImpactAlt":"Seated versions of each stretch."}]'::jsonb, '["Stop if you feel chest pain, dizziness or unusual shortness of breath, and speak to a health professional.","Clear a safe space, wear supportive footwear and keep water nearby.","You can switch to the low-impact version at any time; it is a full workout, not a lesser one."]'::jsonb, 'published', true),
